// ── SLI calculation from Prometheus metrics (Node.js) ────────────
// Assume we have these counters from prom-client:
//   http_requests_total{status_code}  — total requests by status
//   http_request_duration_seconds     — latency histogram

// In PromQL (run in Grafana / Prometheus rules):
//
// AVAILABILITY SLI (rolling 30-day window):
//   1 - (
//     rate(http_requests_total{status_code=~"5.."}[30d])
//     / rate(http_requests_total[30d])
//   )
//
// LATENCY SLI (fraction of requests < 200ms over 1h):
//   sum(rate(http_request_duration_seconds_bucket{le="0.2"}[1h]))
//     / sum(rate(http_request_duration_seconds_count[1h]))

// ── Error budget burn rate alert ─────────────────────────────────
// A burn rate > 1 means you will exhaust your budget before the window ends.
// Burn rate of 14.4 = using a full month's budget in 2 hours = P1 alert.
//
// Prometheus alerting rule:
// - alert: ErrorBudgetBurnTooFast
//   expr: |
//     (
//       rate(http_requests_total{status_code=~"5.."}[1h])
//       / rate(http_requests_total[1h])
//     ) > (14.4 * 0.001)   # 14.4x burn rate on a 99.9% SLO
//   for: 5m
//   labels:
//     severity: critical
//   annotations:
//     summary: "Error budget burning at 14.4x — 2h to exhaustion"

// ── Toil tracking (simple) ────────────────────────────────────────
// Track toil by logging manual interventions with a counter:
import client from 'prom-client';

const toil = new client.Counter({
  name: 'sre_toil_interventions_total',
  help: 'Count of manual operational interventions — proxy for toil',
  labelNames: ['type'],
});

async function restartStalledWorker(workerId) {
  // This is toil: manual, repetitive, should be automated.
  toil.inc({ type: 'worker_restart' });
  await fetch(`/admin/workers/${workerId}/restart`, { method: 'POST' });
  console.log(`Manually restarted worker ${workerId} — automate this!`);
}

console.log('Track toil counts; when they grow, build automation to eliminate them.');
